class TaxAssessment {final int id,invoiceCount;final String name;final double totalIcms,totalIpi;TaxAssessment({required this.id,required this.invoiceCount,required this.name,required this.totalIcms,required this.totalIpi});factory TaxAssessment.fromJson(Map<String,dynamic> j)=>TaxAssessment(id:(j['id'] as num).toInt(),invoiceCount:(j['invoice_count'] as num).toInt(),name:'${j['name']}',totalIcms:double.parse('${j['total_icms']}'),totalIpi:double.parse('${j['total_ipi']}'));}
